import { Card } from '@/types/statistics';
import EmployeesStatistics from '../components/statistics/EmployeesStatistics';
import UserRemoveIcon from '@/components/icons/user/UserRemove';
import GroupIcon from '@/components/icons/user/GroupIcon';
import { useEffect, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { ReviewDashboardStats } from '../types/employeesStats.types';
import EmployeeReviewsList from '../components/reviewsList/EmployeeReviewsList';

export default function EmployeeReviewsPage() {
    const [stats, setStats] = useState<ReviewDashboardStats | null>(null);

    useEffect(() => {
        const fetchStats = async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.review.dashboard });
                setStats(res.data.data);
            } catch (err) {
                setStats(null);
            }
        };
        fetchStats();
    }, []);

    const cards: Card[] = [
        { text: 'إجمالي التقييمات', num: stats?.total_reviews, percent: 12, icon: <GroupIcon /> },
        {
            text: 'متوسط التقييم',
            num: stats?.average_rating != null ? Number(stats.average_rating.toFixed(2)) : undefined,
            percent: 0,
            icon: <UserRemoveIcon />,
        },
    ];

    return (
        <div className="w-full mt-6 mb-20">
            <EmployeesStatistics cards={cards} />
            <EmployeeReviewsList />
        </div>
    );
}
